# Autotuned: runtime selects best XBLOCK/YBLOCK combo
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 512, 'YBLOCK': 1}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 1}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 128, 'YBLOCK': 1}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 512, 'YBLOCK': 2}, num_warps=4, num_stages=3),
        # ... more configs with YBLOCK in {4,8}, XBLOCK in {128,256,512,1024}
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    y0 = yindex % 3
    y1 = yindex // 3
    tl.store(out_ptr + (y0 + 3*x + stride*y1), val, mask)

# Lambda grid lets autotune vary both dimensions
grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # no explicit tile args

